/* Array initialization.
 *
 * NOTE: We store A in a cache-friendly, "column-major" style layout:
 *   - Logically, A is an n×m matrix.
 *   - Physically, we allocate it as A[m][n] and store element (i, k)
 *     at A[k][i]. This lets the optimized Exo kernel access A[k, j]
 *     with j as the innermost index, so loads are contiguous in memory.
 */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* Initialize A with logical value f(i, k) = ((i * k + 1) % n) / n
   * but stored at A[k][i] for better access patterns in the kernel.
   */
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[j][i] = (DATA_TYPE) ((i * j + 1) % n) / n;

  /* Initialize full C (both triangles); the kernel will only update
   * the lower triangular part j <= i, leaving j > i unchanged.
   */
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i * j + 2) % m) / m;
}


