# particular machine; modest defaults are used here.
TILE_J = 32
TILE_K = 32

@proc
def kernel_syrk(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
