    # Phase 1: scale the lower-triangular part of C by beta.
    # ----------------------------------------------------------
    # This loop nest matches the structure of the original kernel:
    # for each row i, only entries j <= i are scaled; the upper
    # triangle (j > i) is left untouched.
    for i in seq(0, n):
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

