    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *  # imported as per guidelines (not used directly here)
from exo.libs.memories import DRAM

# Tiling parameters chosen for decent cache locality without excessive register pressure.
# They can be tuned for a specific target.
TI = 32  # tile size in the i (row) dimension
TJ = 32  # tile size in the j (column) dimension
TK = 32  # tile size in the k (rank) dimension

@proc
def kernel_syrk(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
):
    # Cache alpha and beta into local scalars so that the generated C only
    # loads them once, rather than through the pointer on every use.
    alpha_val: DATA_TYPE
    beta_val: DATA_TYPE
    alpha_val = alpha
    beta_val = beta

    # We implement a blocked lower‑triangular SYRK:
    #   C[i, j] ← beta * C[i, j] + alpha * Σ_k A[i, k] * A[j, k]   for 0 ≤ j ≤ i < n
    #
    # The upper triangle (j > i) is left unchanged.
    #
    # Blocking is done in all three dimensions (i, j, k) using the standard
    # “ceil division + guard” pattern:
    #   for II in 0 .. ceil(n/TI) - 1:
    #     for i_tile in 0 .. TI-1:
    #       i = II*TI + i_tile
    #       if i < n: ...
    #
    # This keeps the code affine for Exo while correctly handling edge tiles.

    # Outer tiling over rows (II) and columns (JJ) of C.
    for II in seq(0, (n + TI - 1) / TI):
        for JJ in seq(0, (n + TJ - 1) / TJ):

            # ------------------------------------------------------------------
            # Phase 1: scale the lower-triangular part of C by beta.
            # We only update C[i, j] when j <= i, exactly as in the original
            # kernel. The rectangular (i,j) block is handled via a guard.
            # ------------------------------------------------------------------
            for i_tile in seq(0, TI):
                i = II * TI + i_tile
                if i < n:
                    for j_tile in seq(0, TJ):
                        j = JJ * TJ + j_tile
                        if j < n and j <= i:
                            C[i, j] = beta_val * C[i, j]

            # ------------------------------------------------------------------
            # Phase 2: rank‑k update on the lower triangle:
            #   C[i, j] += alpha * Σ_k A[i, k] * A[j, k].
            #
            # We tile the reduction dimension k with blocks KK of size TK.
            # Inside each (II, JJ, KK) tile we traverse:
            #   i (within TI), k (within TK), then j (within TJ).
            #
            # For each fixed (i, k) we precompute:
            #   aik = alpha_val * A[i, k]
            # and reuse it across all j within the current j‑tile. This removes
            # one multiplication per (i, j, k) triple, improving ILP and
            # keeping the semantics:
            #   C[i,j] = beta*C[i,j] + alpha*Σ_k A[i,k] * A[j,k]
            # intact (up to the usual floating-point associativity).
            # ------------------------------------------------------------------
            for KK in seq(0, (m + TK - 1) / TK):
                for i_tile in seq(0, TI):
                    i = II * TI + i_tile
                    if i < n:
                        for k_tile in seq(0, TK):
                            k = KK * TK + k_tile
                            if k < m:
                                # Invariant factor for this (i, k) pair within the tile.
                                aik: DATA_TYPE
                                aik = alpha_val * A[i, k]

                                for j_tile in seq(0, TJ):
                                    j = JJ * TJ + j_tile
                                    # Only update valid indices in the lower triangle.
                                    if j < n and j <= i:
                                        C[i, j] += aik * A[j, k]
